// QueueSignatureValues is used to generate a Shared Access Signature (SAS) for an Azure Storage Queue.
// For more information on creating service sas, see https://docs.microsoft.com/rest/api/storageservices/constructing-a-service-sas
// Delegation SAS not supported for queues service
type QueueSignatureValues struct {
	Version                     string    `param:"sv"`  // If not specified, this defaults to Version
	Protocol                    Protocol  `param:"spr"` // See the Protocol* constants
	StartTime                   time.Time `param:"st"`  // Not specified if IsZero
	ExpiryTime                  time.Time `param:"se"`  // Not specified if IsZero
	Permissions                 string    `param:"sp"`  // Create by initializing a QueuePermissions and then call String()
	IPRange                     IPRange   `param:"sip"`
	Identifier                  string    `param:"si"`
	QueueName                   string
	AuthorizedObjectID          string // saoid
	UnauthorizedObjectID        string // suoid
	CorrelationID               string // scid
	SignedDelegatedUserObjectID string // sduoid
}

// SignWithSharedKey uses an account's SharedKeyCredential to sign this signature values to produce the proper SAS query parameters.
func (v QueueSignatureValues) SignWithSharedKey(sharedKeyCredential *SharedKeyCredential) (QueryParameters, error) {
	if v.Identifier == "" && (v.ExpiryTime.IsZero() || v.Permissions == "") {
		return QueryParameters{}, errors.New("service SAS is missing at least one of these: ExpiryTime or Permissions")
	}

	// Make sure the permission characters are in the correct order
	perms, err := parseQueuePermissions(v.Permissions)
	if err != nil {
		return QueryParameters{}, err
	}
	v.Permissions = perms.String()
	if v.Version == "" {
		v.Version = Version
	}
	startTime, expiryTime := formatTimesForSigning(v.StartTime, v.ExpiryTime)

	signedIdentifier := v.Identifier

	// String to sign: http://msdn.microsoft.com/en-us/library/azure/dn140255.aspx
	stringToSign := strings.Join([]string{
		v.Permissions,
		startTime,
		expiryTime,
		getCanonicalName(sharedKeyCredential.AccountName(), v.QueueName),
		signedIdentifier,
		v.IPRange.String(),
		string(v.Protocol),
		v.Version},
		"\n")

	signature, err := exported.ComputeHMACSHA256(sharedKeyCredential, stringToSign)
	if err != nil {
		return QueryParameters{}, err
	}

	p := QueryParameters{
		// Common SAS parameters
		version:     v.Version,
		protocol:    v.Protocol,
		startTime:   v.StartTime,
		expiryTime:  v.ExpiryTime,
		permissions: v.Permissions,
		ipRange:     v.IPRange,
		// Calculated SAS signature
		signature:  signature,
		identifier: signedIdentifier,
	}

	return p, nil
}

// SignWithUserDelegation uses an account's UserDelegationCredential to sign this signature values to produce the proper SAS query parameters.
func (v QueueSignatureValues) SignWithUserDelegation(userDelegationCredential *UserDelegationCredential) (QueryParameters, error) {
	if userDelegationCredential == nil {
		return QueryParameters{}, fmt.Errorf("cannot sign SAS query without User Delegation Key")
	}

	if v.ExpiryTime.IsZero() || v.Permissions == "" {
		return QueryParameters{}, errors.New("user delegation SAS is missing at least one of these: ExpiryTime or Permissions")
	}

	perms, err := parseQueuePermissions(v.Permissions)
	if err != nil {
		return QueryParameters{}, err
	}
	v.Permissions = perms.String()

	if v.Version == "" {
		v.Version = Version
	}
	startTime, expiryTime := formatTimesForSigning(v.StartTime, v.ExpiryTime)

	udk := exported.GetUDKParams(userDelegationCredential)
	udkStart := formatTime(udk.SignedStart, "")
	udkExpiry := formatTime(udk.SignedExpiry, "")

	var signedDelegatedUserTenantID string
	if udk.SignedDelegatedUserTenantID != nil {
		signedDelegatedUserTenantID = *udk.SignedDelegatedUserTenantID
	}

	stringToSign := strings.Join([]string{
		v.Permissions,
		startTime,
		expiryTime,
		getCanonicalName(exported.GetAccountName(userDelegationCredential), v.QueueName),
		*udk.SignedOID,
		*udk.SignedTID,
		udkStart,
		udkExpiry,
		*udk.SignedService,
		*udk.SignedVersion,
		v.AuthorizedObjectID,
		v.UnauthorizedObjectID,
		v.CorrelationID,
		signedDelegatedUserTenantID,
		v.SignedDelegatedUserObjectID,
		v.IPRange.String(),
		string(v.Protocol),
		v.Version},
		"\n")

	signature, err := exported.ComputeUDCHMACSHA256(userDelegationCredential, stringToSign)
	if err != nil {
		return QueryParameters{}, err
	}

	p := QueryParameters{
		version:                     v.Version,
		protocol:                    v.Protocol,
		startTime:                   v.StartTime,
		expiryTime:                  v.ExpiryTime,
		permissions:                 v.Permissions,
		ipRange:                     v.IPRange,
		signature:                   signature,
		identifier:                  v.Identifier,
		authorizedObjectID:          v.AuthorizedObjectID,
		unauthorizedObjectID:        v.UnauthorizedObjectID,
		correlationID:               v.CorrelationID,
		signedDelegatedUserObjectID: v.SignedDelegatedUserObjectID,
	}

	p.signedOID = *udk.SignedOID
	p.signedTID = *udk.SignedTID
	p.signedStart = *udk.SignedStart
	p.signedExpiry = *udk.SignedExpiry
	p.signedService = *udk.SignedService
	p.signedVersion = *udk.SignedVersion
	p.signedDelegatedUserTenantID = signedDelegatedUserTenantID

	return p, nil
}

// getCanonicalName computes the canonical name for a queue resource for SAS signing.
func getCanonicalName(account string, queueName string) string {
	elements := []string{"/queue/", account, "/", queueName}
	return strings.Join(elements, "")
}

// QueuePermissions type simplifies creating the permissions string for an Azure Storage Queue SAS.
// Initialize an instance of this type and then call its String method to set QueueSignatureValues' Permissions field.
type QueuePermissions struct {
	Read, Add, Update, Process bool
}

// String produces the SAS permissions string for an Azure Storage Queue.
// Call this method to set QueueSignatureValues' Permissions field.
func (p *QueuePermissions) String() string {
	var b bytes.Buffer
	if p.Read {
		b.WriteRune('r')
	}
	if p.Add {
		b.WriteRune('a')
	}
	if p.Update {
		b.WriteRune('u')
	}
	if p.Process {
		b.WriteRune('p')
	}
	return b.String()
}

// Parse initializes the QueuePermissions' fields from a string.
func parseQueuePermissions(s string) (QueuePermissions, error) {
	p := QueuePermissions{}
	for _, r := range s {
		switch r {
		case 'r':
			p.Read = true
		case 'a':
			p.Add = true
		case 'u':
			p.Update = true
		case 'p':
			p.Process = true
		default:
			return QueuePermissions{}, fmt.Errorf("invalid permission: '%v'", r)
		}
	}
	return p, nil
}
